// 原Office已经核验的更职原因只映射真实已接受交接，不借今日持有人反造签受；完整本域资格随后另验。
#include "political_term_handover_rules.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
Outcome<std::optional<PoliticalHeadSource>> read_political_term_handover_head_source(const CommonStore& c,const PoliticalTermHandoverCatalog& catalog,const PoliticalTermHandoverState& state,const PoliticalSuccessorRoundCatalog& rounds,const PoliticalSuccessionPolicy& original,const PoliticalSuccessionOfficeSource& office){
 auto fail=[](const StableId& id)->Outcome<std::optional<PoliticalHeadSource>>{return {false,{},common_failure("PoliticalTermHandoverAppointmentSourceMismatch",id).error};};
 if(catalog.version!=1||state.version!=1||rounds.version!=1||office.observed_tick<0||office.observed_tick>c.tick()||office.vacant||!office.holder_actor_id)return fail(original.id);
 const PoliticalTermHandoverAnswer* answer=nullptr;for(const auto& row:state.answers.rows())if(row.second.office_change_fact_id==office.latest_office_fact_id){if(answer||row.first!=row.second.id)return fail(row.first);answer=&row.second;}if(!answer)return {true,std::nullopt,{}};
 const auto* offer=state.offers.find(answer->offer_fact_id);const auto* policy=offer?catalog.policies.find(offer->policy_id):nullptr;const auto* round=policy?rounds.policies.find(policy->successor_round_policy_id):nullptr;const auto number=political_term_handover_fact_sequence(c,answer->id),change=organization_instance_sequence(office.latest_office_fact_id,"organization");const auto* header=c.state().facts.find(answer->id);const auto& order=c.state().facts.order();const auto at=std::find(order.begin(),order.end(),answer->id);const auto* change_header=c.state().facts.find(office.latest_office_fact_id);
 if(!answer->accepted||!answer->player_receipt||answer->actor_id!=*office.holder_actor_id||answer->installed_office_epoch!=office.office_epoch||answer->expected_office_epoch==INT64_MAX||answer->installed_office_epoch!=answer->expected_office_epoch+1||answer->tick<0||answer->tick>office.observed_tick||!number||!header||header->kind!="political_term_handover_accepted"||!change||*number==INT64_MAX||*change!=*number+1||!change_header||change_header->id!=office.latest_office_fact_id||change_header->kind!="organization_office_changed"||change_header->domain!="organization"||at==order.end()||std::next(at)==order.end()||*std::next(at)!=office.latest_office_fact_id||!offer||offer->id!=answer->offer_fact_id||!policy||!round||round->succession_policy_id!=original.id||offer->organization_id!=original.organization_id||offer->office_id!=original.leader_office_id||offer->candidate_actor_id!=answer->actor_id||offer->office_epoch!=answer->expected_office_epoch)return fail(answer->id);
 if(!office.before_fact_id.empty()){const auto end=std::find(order.begin(),order.end(),office.before_fact_id);if(end==order.end()||std::next(at)>=end)return fail(answer->id);}
 PoliticalHeadSource out;out.source_identity=c.state().identity;out.policy_id=original.id;out.organization_id=original.organization_id;out.office_id=original.leader_office_id;out.actor_id=answer->actor_id;out.predecessor_actor_id=offer->issuer_actor_id;out.source_fact_id=answer->id;out.office_change_fact_id=office.latest_office_fact_id;out.before_fact_id=office.before_fact_id;out.origin=PoliticalHeadOrigin::term_handover;out.office_epoch=office.office_epoch;out.installed_tick=answer->tick;out.observed_tick=office.observed_tick;return {true,std::move(out),{}};
}
}
